// ---- constants (as tblite and the reference script use them) ----
const BOHR = 0.529177210903;             // Å per Bohr
const AATOAU = 1 / BOHR;
const AUTOEV = 27.211386245988;          // eV per Hartree (output)
const EVTOAU = 1 / 27.21138505;          // GFN1 keeps the older value for its eV parameters
const KT_DEFAULT = 300.0 * 3.166808578545117e-06; // 300 K in Hartree (tblite default)
const MAX_ELEM = 86;

// GFN1 global parameters (gfn1.f90)
const REP_KEXP = 1.5, REP_REXP = 1.0;
const KDIAG = [1.85, 2.25, 2.0, 2.0, 2.0];
const ENSCALE = -7.0e-3;
const KDIFF = 2.85;
const kshell = (k, l) => ((k === 0 && l === 1) || (l === 0 && k === 1)) ? 2.08 : (KDIAG[l] + KDIAG[k]) / 2;

// Cutoffs (Bohr) and SCC settings
const CN_KCN = 16.0, CN_CUTOFF = 25.0;
const REP_CUTOFF = 25.0;
// integral screening exponent: clip(25 - 10*log10(accuracy), 5, 25) (basis/type.f90), 25 at accuracy <= 1
const integralCutoff = acc => Math.min(Math.max(25 - 10 * Math.log10(Math.min(Math.max(acc, 1e-4), 1e3)), 5), 25);
